#!/usr/bin/env node
// Turn the one native-op list into TypeScript declarations.
// Source: crates/tekto-native/native-ops.json
// Target: packages/core/src/native-ops.d.ts
import { readFileSync, writeFileSync } from "node:fs";

const root = new URL("..", import.meta.url);
const source = new URL("crates/tekto-native/native-ops.json", root);
const target = new URL("packages/core/src/native-ops.d.ts", root);
const spec = JSON.parse(readFileSync(source, "utf8"));
const names = new Set();
const lines = [
  "// Generated by scripts/generate-native-types.mjs from crates/tekto-native/native-ops.json. Do not edit by hand.",
  "export type NativeOp =",
];
spec.ops.forEach((entry, index) => {
  if (!entry.name || typeof entry.name !== "string") throw new Error(`op ${index} needs a name`);
  if (names.has(entry.name)) throw new Error(`duplicate native op ${entry.name}`);
  names.add(entry.name);
  if (!entry.example || entry.example.op !== entry.name) {
    throw new Error(`op ${entry.name} needs an example whose op is its name`);
  }
  const args = Object.entries(entry.args ?? {}).map(([key, type]) => {
    if (typeof type !== "string" || !type) throw new Error(`op ${entry.name}.${key} needs a type`);
    return `; ${key}: ${type}`;
  });
  lines.push(`  | { op: "${entry.name}"${args.join("")} }`);
});
lines.push("  ;", "");
const output = lines.join("\n");
if (process.argv.includes("--check")) {
  const normalize = (text) => text.replace(/\r\n/g, "\n");
  if (normalize(readFileSync(target, "utf8")) !== normalize(output)) {
    throw new Error("native op types are stale; run node scripts/generate-native-types.mjs");
  }
} else {
  writeFileSync(target, output);
}
